/* ContextMenu: a region that answers a right-click, and the shared menu list
   (MenuList.module.css) opened where the pointer is. */

.region {
  display: grid;
  place-items: center;
  min-width: var(--context-region-width, 300px);
  min-height: var(--context-region-height, 150px);
  padding: 16px;
  border: var(--border-w) dashed var(--line-input);
  border-radius: var(--context-region-radius, var(--r-lg));
  background: rgba(var(--rgb-white), 0.3);
  font-size: var(--text-small);
  color: var(--ink-muted);
  text-align: center;
  -webkit-touch-callout: none;
}

.live {
  outline: none;
  transition: background-color var(--dur) var(--ease);
}

.live:focus-visible {
  box-shadow: var(--focus-ring);
}

.live[aria-expanded="true"] {
  background: var(--wash-subtle);
}

.floating {
  position: fixed;
  z-index: var(--z-popover);
  animation: pop-in var(--dur-slow) var(--ease-out);
}

/* Inline: the region and the open menu share one grid cell, the menu
   dropped in from where a pointer would have pressed. Both stay in the page
   flow, so the specimen measures as one block. */
.inlineStage {
  display: grid;
  grid-template-areas: "stack";
}

.inlineStage > * {
  grid-area: stack;
}

.inlineStage .region {
  align-self: start;
  justify-self: start;
  place-items: start;
}

.inlineMenu {
  align-self: start;
  justify-self: start;
  margin: 56px 0 0 140px;
}

@media (prefers-reduced-motion: reduce) {
  .floating {
    animation: fade-in var(--dur) linear;
  }
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent, type MouseEvent, type PointerEvent, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import { Portal } from "../_internal/portal";
import styles from "./ContextMenu.module.css";
import { MenuList, type MenuListEntry } from "./menu-list";

export type { MenuListAction as ContextMenuAction, MenuListEntry as ContextMenuEntry } from "./menu-list";

export type ContextMenuProps = {
  /** The region that answers a right-click: a row, a card, a canvas. */
  children: ReactNode;
  /** The menu: actions, separators ({ id, separator: true }) and headings ({ id, heading }). */
  items: ReadonlyArray<MenuListEntry>;
  /** The menu's accessible name, e.g. "Actions for Invoice INV-0042". */
  label: string;
  /** ms a touch must be held to open it on phones and tablets. */
  longPressMs?: number;
  /**
   * Render the menu open in the page flow, over the region (docs, previews).
   * Nothing is interactive and no listeners are attached.
   */
  inline?: boolean;
  /** Inline only: the item drawn in its hover state. */
  highlightId?: string;
  className?: string;
};

/**
 * A menu of actions for a region, opened where the pointer is with a
 * right-click, with Shift+F10 or the Menu key while the region has focus, or
 * with a long press on touch. Focus moves to the first item; arrows, Home,
 * End and typeahead move; Enter runs; Esc or Tab closes and returns focus to
 * the region. Every action must also be reachable some other way: a context
 * menu is a shortcut, never the only route.
 */
export function ContextMenu({ children, items, label, longPressMs = 500, inline, highlightId, className }: ContextMenuProps) {
  const [at, setAt] = useState<{ x: number; y: number } | null>(null);
  const regionRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const press = useRef(0);
  const id = useId();

  const close = (reason: "select" | "escape" | "tab" | "outside") => {
    setAt(null);
    if (reason === "escape" || reason === "select") regionRef.current?.focus();
  };

  // Keep the menu inside the viewport once it has a size.
  useLayoutEffect(() => {
    const m = menuRef.current;
    if (!at || !m) return;
    const r = m.getBoundingClientRect();
    const x = Math.max(8, Math.min(at.x, window.innerWidth - r.width - 8));
    const y = Math.max(8, Math.min(at.y, window.innerHeight - r.height - 8));
    m.style.left = `${x}px`;
    m.style.top = `${y}px`;
  }, [at]);

  useEffect(() => {
    if (!at) return;
    const onDown = (e: globalThis.PointerEvent) => {
      if (menuRef.current?.contains(e.target as Node)) return;
      close("outside");
    };
    const onScroll = () => close("outside");
    document.addEventListener("pointerdown", onDown, true);
    window.addEventListener("resize", onScroll);
    window.addEventListener("scroll", onScroll, true);
    return () => {
      document.removeEventListener("pointerdown", onDown, true);
      window.removeEventListener("resize", onScroll);
      window.removeEventListener("scroll", onScroll, true);
    };
  }, [at]);

  if (inline) {
    return (
      <div className={cx(styles.inlineStage, className)}>
        <div className={styles.region} aria-hidden="true">
          {children}
        </div>
        <MenuList entries={items} label={label} onClose={() => {}} inert highlightId={highlightId} className={styles.inlineMenu} />
      </div>
    );
  }

  const openAt = (x: number, y: number) => setAt({ x, y });

  return (
    <>
      <div data-slot="context-menu"
        ref={regionRef}
        className={cx(styles.region, styles.live, className)}
        tabIndex={0}
        aria-haspopup="menu"
        aria-expanded={Boolean(at)}
        aria-controls={at ? id : undefined}
        aria-description="Right-click or press Shift F10 for actions"
        onContextMenu={(e: MouseEvent<HTMLDivElement>) => {
          e.preventDefault();
          openAt(e.clientX, e.clientY);
        }}
        onKeyDown={(e: KeyboardEvent<HTMLDivElement>) => {
          if ((e.shiftKey && e.key === "F10") || e.key === "ContextMenu") {
            e.preventDefault();
            const r = e.currentTarget.getBoundingClientRect();
            openAt(r.left + 16, r.top + 16);
          }
        }}
        onPointerDown={(e: PointerEvent<HTMLDivElement>) => {
          if (e.pointerType !== "touch") return;
          const { clientX, clientY } = e;
          press.current = window.setTimeout(() => openAt(clientX, clientY), longPressMs);
        }}
        onPointerUp={() => window.clearTimeout(press.current)}
        onPointerCancel={() => window.clearTimeout(press.current)}
        onPointerMove={() => window.clearTimeout(press.current)}
      >
        {children}
      </div>
      {at ? (
        <Portal>
          <MenuList
            ref={menuRef}
            id={id}
            entries={items}
            label={label}
            autoFocus
            onClose={close}
            className={styles.floating}
            style={{ left: at.x, top: at.y }}
          />
        </Portal>
      ) : null}
    </>
  );
}

"use client";

import { forwardRef, useEffect, useRef, type CSSProperties, type KeyboardEvent, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import { mergeRefs } from "../_internal/merge-refs";
import styles from "./MenuList.module.css";

// The menu list shared by ContextMenu and Menubar: role="menu", roving focus
// (arrows, Home, End, typeahead), separators, headings, shortcuts and danger
// items, drawn in the popover glass.

export type MenuListAction = {
  id: string;
  label: string;
  icon?: ReactNode;
  /** Shown at the right edge, e.g. "Ctrl C". Display only: wire the key yourself. */
  shortcut?: string;
  tone?: "default" | "danger";
  disabled?: boolean;
  onSelect?: () => void;
  separator?: false;
  heading?: undefined;
};
export type MenuListSeparator = { id: string; separator: true };
export type MenuListHeading = { id: string; heading: string; separator?: false };
export type MenuListEntry = MenuListAction | MenuListSeparator | MenuListHeading;

const isAction = (e: MenuListEntry): e is MenuListAction => !("separator" in e && e.separator) && !("heading" in e && e.heading);

/** Focuses the enabled item at index i (negative counts from the end). */
export function focusMenuItem(menu: HTMLElement | null, i: number) {
  const list = Array.from(menu?.querySelectorAll<HTMLElement>('[role="menuitem"]:not([aria-disabled="true"])') ?? []);
  if (list.length) list[((i % list.length) + list.length) % list.length].focus();
}

type Props = {
  entries: ReadonlyArray<MenuListEntry>;
  /** Called after an item runs, or on Esc / Tab. */
  onClose: (reason: "select" | "escape" | "tab") => void;
  label?: string;
  labelledBy?: string;
  id?: string;
  /** Focus the first item on mount. */
  autoFocus?: boolean;
  /** Extra keys the parent handles (Menubar's Left and Right). Return true if handled. */
  onKeyExtra?: (e: KeyboardEvent<HTMLDivElement>) => boolean;
  /** No item takes focus: a static picture of the menu (docs, previews). */
  inert?: boolean;
  /** Mark one item as highlighted when inert, to show the hover state. */
  highlightId?: string;
  className?: string;
  style?: CSSProperties;
};

export const MenuList = forwardRef<HTMLDivElement, Props>(function MenuList(
  { entries, onClose, label, labelledBy, id, autoFocus, onKeyExtra, inert, highlightId, className, style },
  ref,
) {
  const rootRef = useRef<HTMLDivElement>(null);
  const typed = useRef({ text: "", at: 0 });

  const items = () => Array.from(rootRef.current?.querySelectorAll<HTMLElement>('[role="menuitem"]:not([aria-disabled="true"])') ?? []);
  const focusAt = (i: number) => focusMenuItem(rootRef.current, i);

  useEffect(() => {
    if (!autoFocus || inert) return;
    const frame = requestAnimationFrame(() => focusAt(0));
    return () => cancelAnimationFrame(frame);
  }, [autoFocus, inert]);

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (onKeyExtra?.(e)) return;
    const list = items();
    const at = list.indexOf(document.activeElement as HTMLElement);
    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        focusAt(at + 1);
        return;
      case "ArrowUp":
        e.preventDefault();
        focusAt(at < 0 ? -1 : at - 1);
        return;
      case "Home":
        e.preventDefault();
        focusAt(0);
        return;
      case "End":
        e.preventDefault();
        focusAt(-1);
        return;
      case "Escape":
        e.preventDefault();
        e.stopPropagation();
        onClose("escape");
        return;
      case "Tab":
        onClose("tab");
        return;
    }
    if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
      const now = Date.now();
      typed.current = { text: (now - typed.current.at > 600 ? "" : typed.current.text) + e.key.toLowerCase(), at: now };
      const start = at + 1;
      const order = [...list.slice(start), ...list.slice(0, start)];
      const hit = order.find((el) => (el.textContent ?? "").trim().toLowerCase().startsWith(typed.current.text));
      hit?.focus();
    }
  };

  return (
    <div
      ref={mergeRefs(rootRef, ref)}
      id={id}
      role="menu"
      aria-label={label}
      aria-labelledby={labelledBy}
      aria-orientation="vertical"
      className={cx(styles.menu, className)}
      style={style}
      onKeyDown={onKeyDown}
      tabIndex={-1}
    >
      {entries.map((entry) => {
        if ("separator" in entry && entry.separator) return <div key={entry.id} role="separator" className={styles.separator} />;
        if ("heading" in entry && entry.heading)
          return (
            <div key={entry.id} role="presentation" className={styles.heading}>
              {entry.heading}
            </div>
          );
        if (!isAction(entry)) return null;
        return (
          <div
            key={entry.id}
            role="menuitem"
            tabIndex={-1}
            aria-disabled={entry.disabled || undefined}
            data-highlighted={inert && highlightId === entry.id ? "" : undefined}
            className={cx(styles.item, entry.tone === "danger" && styles.danger, entry.disabled && styles.disabled)}
            onPointerMove={(e) => {
              if (!inert && !entry.disabled && document.activeElement !== e.currentTarget) e.currentTarget.focus();
            }}
            onClick={() => {
              if (inert || entry.disabled) return;
              entry.onSelect?.();
              onClose("select");
            }}
            onKeyDown={(e) => {
              if ((e.key === "Enter" || e.key === " ") && !entry.disabled && !inert) {
                e.preventDefault();
                entry.onSelect?.();
                onClose("select");
              }
            }}
          >
            {entry.icon ? (
              <span className={styles.icon} aria-hidden="true">
                {entry.icon}
              </span>
            ) : null}
            <span className={styles.label}>{entry.label}</span>
            {entry.shortcut ? (
              <kbd className={styles.shortcut} aria-label={`Shortcut ${entry.shortcut}`}>
                {entry.shortcut}
              </kbd>
            ) : null}
          </div>
        );
      })}
    </div>
  );
});

/* The menu list shared by ContextMenu and Menubar: the same popover glass
   and item rhythm as Menu and Select, so every popup is one family. */

.menu {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: var(--menu-list-min-width, 220px);
  max-width: min(320px, calc(100vw - 16px));
  padding: var(--popover-pad, calc(6px * var(--density)));
  background: var(--popover-surface);
  -webkit-backdrop-filter: var(--popover-blur);
  backdrop-filter: var(--popover-blur);
  border: var(--border-w) solid var(--popover-border);
  border-radius: var(--popover-radius, var(--r-lg));
  box-shadow: var(--popover-shadow);
  outline: none;
}

.heading {
  padding: 8px 10px 4px;
  font-size: var(--text-micro);
  font-weight: 700;
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
  color: var(--ink-muted);
  user-select: none;
}

.item {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 34px;
  padding: calc(7px * var(--density)) calc(10px * var(--density));
  border-radius: var(--popover-item-radius, var(--r-xs));
  font-size: 13.5px;
  line-height: 1.35;
  color: var(--ink-body);
  cursor: pointer;
  outline: none;
  user-select: none;
  transition:
    background-color var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease);
}

.item:focus,
.item[data-highlighted] {
  background: var(--popover-item-active-bg, linear-gradient(to right, rgba(var(--rgb-brand), 0.14), rgba(var(--rgb-brand-deep), 0.07)));
  color: var(--ink-brand);
}

.item:active {
  background: var(--popover-item-press-bg, linear-gradient(to right, rgba(var(--rgb-brand), 0.2), rgba(var(--rgb-brand-deep), 0.1)));
}

.item:focus-visible {
  box-shadow: inset 0 0 0 1.5px rgba(var(--rgb-brand), 0.55);
}

.icon {
  display: inline-flex;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  color: var(--ink-muted);
}

.icon svg {
  width: 16px;
  height: 16px;
}

.item:focus .icon,
.item[data-highlighted] .icon {
  color: var(--ink-brand);
}

.label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shortcut {
  margin-left: 16px;
  font-family: var(--font-body);
  font-size: var(--text-caption);
  letter-spacing: 0.04em;
  color: var(--ink-muted);
}

.danger,
.danger .icon {
  color: var(--danger-ink);
}

.danger:focus,
.danger[data-highlighted] {
  background: linear-gradient(to right, rgba(var(--rgb-danger), 0.12), rgba(var(--rgb-danger), 0.05));
  color: var(--danger-ink);
}

.danger:focus .icon {
  color: var(--danger-ink);
}

.disabled,
.disabled:focus {
  cursor: not-allowed;
  background: transparent;
  color: var(--ink-disabled);
}

.disabled .icon,
.disabled .shortcut {
  color: var(--ink-disabled);
}

.separator {
  height: 1px;
  margin: 5px -6px;
  background: var(--line-soft);
}
